	//
	// We explicitly express an i-outer, j-inner traversal using for_dims<'i'>
	// followed by for_each over the remaining dimension. This makes the
	// loop structure obvious to both the reader and the compiler and matches
	// the chosen row-major layout (j is the fastest-varying index).
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// state with fixed i
		auto si = trav_i.state();
		auto i  = get_index<'i'>(si);

		trav_i.for_each([&](auto state) {
			auto j = get_index<'j'>(state);
			num_t numerator = static_cast<num_t>((i + j) % n_len_A);
			A[state] = numerator / denom;
		});
	});
