	// We build a traverser over A and x only; tmp and y are updated via the
	// index states produced by this traverser. This keeps the proto-structure
	// application (blocking) limited to the arrays that actually have a 'j'
	// dimension.
	auto trav = traverser(A, x).order(j_blocking);

	#pragma scop
	// -------------------------------------------------------------------------
	// Phase 1 & 2 combined structure:
	//   for i in rows:
	//     tmp[i] = sum_j A[i][j] * x[j];
	//     y[j]  += A[i][j] * tmp[i];
	//
	// We still conceptually perform two passes over each row i (one to build
	// tmp[i], one to update y), but we:
	//   - keep tmp[i] in a scalar register during the accumulation
	//   - use a tiled traversal over j to improve cache locality on x and A
	//   - express all loop nests via Noarr traversers
	// -------------------------------------------------------------------------
	trav.template for_dims<'i'>([&](auto trav_i) {
		// This state contains only the fixed 'i' index and is suitable for
		// indexing tmp (which has dimension 'i' only).
		auto si = trav_i.state();

		// Accumulator for tmp[i], kept in a register for the duration of the
		// summation over j. This avoids repeated loads/stores of tmp[i] inside
		// the inner loop and makes vectorization easier for the compiler.
		num_t tmp_i = static_cast<num_t>(0);

		// ------------------------- Phase 1: tmp[i] --------------------------
		//
		// for each block J of the j-dimension, traverse all valid j inside
		// that block and accumulate into tmp_i.
		trav_i.template for_dims<'J'>([&](auto trav_J) {
			// for_each here iterates the remaining dimensions, which are the
			// j coordinate inside the current block plus the internal presence
			// flag of into_blocks_dynamic. The state we get still contains
			// the original dimensions ('i' and 'j') only; the block structure
			// is handled internally by the traverser.
			trav_J.for_each([&](auto s) {
				tmp_i += A[s] * x[s];
			});
		});

		// Materialize tmp[i] once after the accumulation is complete.
		tmp[si] = tmp_i;

		// ------------------------- Phase 2: y[j] ---------------------------
		//
		// Using the same tiled traversal over j, update each y[j] with
		// A[i][j] * tmp[i]. The order of floating-point operations on each
		// y[j] is unchanged relative to the original kernel: for each i, j
		// is still visited in increasing order, only grouped into blocks.
		trav_i.template for_dims<'J'>([&](auto trav_J) {
			trav_J.for_each([&](auto s) {
				y[s] += A[s] * tmp_i;
			});
		});
	});
	#pragma endscop
}

