	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	num_t fn = static_cast<num_t>(n_len);

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([&](auto state) {
		auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) / fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// A[i][j] = ((i + j) % n) / (5 * m)
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t numerator = static_cast<num_t>((i + j) % n_len_A);
		num_t denom = static_cast<num_t>(5 * m_len);
		A[state] = numerator / denom;
	});
}

// Main computational kernel
//
// Computes:
//   tmp[i] = sum_j A[i][j] * x[j]
//   y[j]   = sum_i A[i][j] * tmp[i]  = (A^T * tmp)[j]
//
// The implementation uses Noarr traversers only (no manual for-loops) and
// applies the following optimizations:
//
// 1) Register accumulation for tmp[i] so each tmp[i] is written exactly once.
// 2) Blocked computation of y in the j-dimension to improve cache locality of y.
//    We partition columns into blocks of size tuning::j_block_size and, for
//    each block, accumulate contributions into a small temporary vector that
//    fits into cache, then flush it into y in one pass.
// 3) Correct handling of the case when N is not divisible by the block size
//    via a tail region processed with the straightforward traversal.
//
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	#pragma scop
	// ---------------------------------------------------------------------
	// Phase 0: y[j] = 0 for all j
	// ---------------------------------------------------------------------
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// ---------------------------------------------------------------------
	// Phase 1: tmp[i] = sum_j A[i][j] * x[j]
	//   We do a row-wise traversal (i fixed, then j) and accumulate tmp[i]
	//   in a scalar register, writing it back once per row.
	// ---------------------------------------------------------------------
	traverser(A, x, tmp).template for_dims<'i'>([&](auto inner) {
		// state with fixed i
		auto si = inner.state(); // contains only 'i'
		num_t acc = static_cast<num_t>(0);

		// for all j: acc += A[i][j] * x[j]
		inner.for_each([&](auto state) {
			acc += A[state] * x[state];
		});

		// single store to tmp[i]
		tmp[si] = acc;
	});

	// ---------------------------------------------------------------------
	// Phase 2: y[j] = sum_i A[i][j] * tmp[i] = (A^T * tmp)[j]
	//
	// We perform this as:
	//   - A blocked part over j (head), where we use a small temporary
	//     vector of length j_block_size for each column block.
	//   - A tail part (if N is not a multiple of j_block_size) processed
	//     with a straightforward traversal.
	// ---------------------------------------------------------------------

	// Length in the j-dimension (common for A, x, y)
	auto n_len = A | get_length<'j'>();

	constexpr std::size_t J_BLOCK = tuning::j_block_size;
	const std::size_t full_blocks = n_len / J_BLOCK;
	const std::size_t head_len    = full_blocks * J_BLOCK;
	const std::size_t tail_len    = n_len - head_len;

	// ------------------------ Blocked head part -------------------------
	if (head_len > 0) {
		// Restrict A and y to the first `head_len` columns [0, head_len)
		auto A_head = A ^ slice<'j'>(0, head_len);
		auto y_head = y ^ slice<'j'>(0, head_len);

		// Split the j-dimension into blocks:
		//   original 'j' -> 'J' (block index), 'j' (index within block)
		// Each block has static length J_BLOCK, and head_len is divisible by J_BLOCK.
		auto A_block = A_head ^ into_blocks<'j', 'J', 'j'>(noarr::lit<J_BLOCK>);

		// For flushing, we use a blocked view on y as well:
		//   original 'j' -> 'J', 'b'
		// where 'b' is the local index within a block (0 .. J_BLOCK-1).
		auto y_blocked = y_head ^ into_blocks<'j', 'J', 'b'>(noarr::lit<J_BLOCK>);

		// Local buffer for one y-block:
		//   dimension 'b' with static length J_BLOCK
		auto y_local     = make_bag(scalar<num_t>() ^ array<'b', J_BLOCK>());
		auto y_local_ref = y_local.get_ref();

		// Traverse blocks in the j-dimension (dimension 'J')
		traverser(A_block, tmp).template for_dims<'J'>([&](auto trav_J) {
			// -----------------------------------------------------------------
			// For the current column block J, we compute:
			//   y_local[b] = sum_i A[i, J*J_BLOCK + b] * tmp[i]
			// for b in 0 .. J_BLOCK-1, then add y_local into the block of y.
			// -----------------------------------------------------------------

			// 1) Zero the local block buffer
			traverser(y_local_ref).for_each([&](auto sb) {
				y_local_ref[sb] = static_cast<num_t>(0);
			});

			// 2) Accumulate contributions from all rows i for this block
			trav_J.template for_dims<'i'>([&](auto inner_i) {
				auto si = inner_i.state(); // fixed 'i'
				const num_t tmp_i = tmp[si];

				// For this i, walk j inside the current block J
				inner_i.for_each([&](auto state) {
					// state has dimensions: 'i', 'J', 'j' (j is local index within block)
					auto j_local = get_index<'j'>(state); // in [0, J_BLOCK)
					auto sb      = idx<'b'>(j_local);

					y_local_ref[sb] += A_block[state] * tmp_i;
				});
			});

			// 3) Flush local block into the corresponding portion of y
			auto J_state = trav_J.state();            // fixed 'J'
			auto J_index = get_index<'J'>(J_state);   // which block we are in

			// View of y restricted to this particular block 'J'
			auto y_block_view = y_blocked.get_ref() ^ fix<'J'>(J_index);

			// Add y_local into y_block_view element-wise:
			traverser(y_block_view, y_local_ref).for_each([&](auto sb) {
				// 'sb' indexes the 'b' dimension (0 .. J_BLOCK-1)
				y_block_view[sb] += y_local_ref[sb];
			});
		});
	}

	// ------------------------ Tail (remainder) part --------------------
	// If n_len is not a multiple of J_BLOCK, we handle the last
	// `tail_len` columns [head_len, n_len) with a straightforward
	// i-major traversal.
	if (tail_len > 0) {
		auto A_tail = A ^ slice<'j'>(head_len, tail_len);
		auto y_tail = y ^ slice<'j'>(head_len, tail_len);

		traverser(A_tail, tmp, y_tail).template for_dims<'i'>([&](auto inner) {
			auto si = inner.state(); // fixed 'i'

			inner.for_each([&](auto state) {
				// state has 'i' and 'j' (restricted to tail columns)
				y_tail[state] += A_tail[state] * tmp[si];
			});
		});
	}
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// common length proto-structure
	auto set_lengths = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout   ^ set_lengths);
	auto x   = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout   ^ set_lengths);
	auto y   = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout   ^ set_lengths);
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), x.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_atax(A.get_ref(), x.get_ref(), y.get_ref(), tmp.get_ref());

	auto end = std::chrono::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print result vector y
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
