#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "atax.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic 1D proto-structures for the problem dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Layout tuning – kept centralized so it is easy to experiment with
struct tuning {
	// A: m x n, row-major (i = row, j = column)
	// We apply ^ j_vec first, then ^ i_vec:
	//   scalar ^ j_vec => contiguous 'j' (columns),
	//   (...) ^ i_vec  => vector of rows -> standard row-major
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);

	// x: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(x_layout, j_vec);

	// y: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(y_layout, j_vec);

	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);

	// Tuning knobs (currently used implicitly by the compiler, but kept here
	// so they can be wired into blocking/tiling strategies if desired).
	static constexpr std::size_t i_block = 64;
	static constexpr std::size_t j_block = 256;
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------
void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	num_t fn = static_cast<num_t>(n_len);

	// x[j] = 1 + (j / fn)
	// Traverser walks 'j' in order, so we get a simple stride-1 initialization.
	traverser(x).for_each([&](auto state) {
		auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) / fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len   = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// Precompute the denominator once; it is invariant over the whole matrix
	const num_t denom = static_cast<num_t>(5) * static_cast<num_t>(m_len);

	// A[i][j] = ((i + j) % n) / (5 * m)
	// This is written row-major thanks to the A_layout choice.
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t numerator = static_cast<num_t>((i + j) % n_len_A);
		A[state] = numerator / denom;
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
//   ATAX: y = A^T * (A * x)
//   tmp[i] = (A * x)[i]
//   y[j]   = sum_i A[i][j] * tmp[i]
// -----------------------------------------------------------------------------
//
// Noarr-based implementation notes:
//
//  * The outer traversal is over the row dimension 'i', which matches the
//    row-major layout of A (tuning.A_layout) and thus gives good spatial
//    locality for A.
//  * For each row i, we accumulate tmp[i] in a scalar register (tmp_i).
//    This avoids repeated loads/stores of tmp[i] inside the inner loop and
//    lets the compiler keep the partial sum in a register, which substantially
//    improves bandwidth and allows better vectorization.
//  * We still traverse 'j' in monotonically increasing order, so the sequence
//    of floating-point operations for each accumulation remains identical to
//    the simple nested for-loops, preserving numerical behavior.
//  * y is initialized in a separate pass using a traverser, keeping the whole
//    computation within the Noarr abstractions.
//
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	#pragma scop
	// ---------------------------------------------------------------------
	// 1) Initialize y: for (j = 0; j < N; j++) y[j] = 0;
	// ---------------------------------------------------------------------
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// ---------------------------------------------------------------------
	// 2) Main computation:
	//    for (i = 0; i < M; i++) {
	//      tmp[i] = 0;
	//      for (j = 0; j < N; j++)
	//        tmp[i] += A[i][j] * x[j];
	//      for (j = 0; j < N; j++)
	//        y[j] += A[i][j] * tmp[i];
	//    }
	//
	// Implemented using a Noarr traverser:
	//  - outer dimension: 'i' (rows)
	//  - inner dimension: 'j' (columns), traversed twice
	// ---------------------------------------------------------------------
	traverser(A, x, y, tmp).template for_dims<'i'>([&](auto inner) {
		// State with fixed i (row index). This can be used directly to index
		// tmp[i] and A[i, j] (once 'j' is added by the inner traversal).
		auto si = inner.state();

		// Accumulate tmp[i] in a scalar register to avoid repeated memory
		// traffic on tmp[i] inside the inner loop.
		num_t tmp_i = static_cast<num_t>(0);

		// First inner loop over 'j':
		//   tmp_i = sum_j A[i][j] * x[j];
		inner.template for_each<'j'>([&](auto state) {
			// state contains both 'i' and 'j'
			tmp_i += A[state] * x[state];
		});

		// Write the final accumulated value once to tmp[i].
		tmp[si] = tmp_i;

		// Second inner loop over 'j':
		//   y[j] += A[i][j] * tmp[i];
		// We reuse tmp_i directly from the register instead of loading from
		// tmp[si] in each iteration.
		inner.template for_each<'j'>([&](auto state) {
			y[state] += A[state] * tmp_i;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// common length proto-structure
