	auto n_len_A = A | get_length<'j'>();

	// A[i][j] = ((i + j) % n) / (5 * m)
	// Precompute 1 / (5 * m) once; this is constant across A.
	num_t inv_denom = static_cast<num_t>(1) / static_cast<num_t>(5 * m_len);

	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t numerator = static_cast<num_t>((i + j) % n_len_A);
		A[state] = numerator * inv_denom;
	});
