// -----------------------------------------------------------------------------
// Main computational kernel
//   ATAX: y = A^T * (A * x)
// -----------------------------------------------------------------------------
//
// The original algorithm (in index form) is:
//
//   for (i = 0; i < N; i++) y[i] = 0;
//   for (i = 0; i < M; i++) {
//     tmp[i] = 0;
//     for (j = 0; j < N; j++)
//       tmp[i] += A[i][j] * x[j];
//   }
//   for (j = 0; j < N; j++)
//     for (i = 0; i < M; i++)
//       y[j] += A[i][j] * tmp[i];
//
// This implementation keeps the same mathematical result but:
//   * uses a row-major layout for A (rows contiguous in 'j'),
//   * accumulates tmp[i] in a local scalar (reducing memory traffic),
//   * tiles the row dimension 'i' with into_blocks_static, exposing
//     a tunable block size for cache-friendly traversal.
//   * all loops are expressed via Noarr traversers.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	// -------------------------------------------------------------------------
	// 1) Initialize y to zero: y[j] = 0
	// -------------------------------------------------------------------------
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// -------------------------------------------------------------------------
	// 2) Main computation with row blocking in dimension 'i'
	//
	// We block the row dimension 'i' to improve cache locality when streaming
	// rows of A and reusing the vector x within a block of rows.
	//
	// into_blocks_static<'i','b','I','i'>(B):
	//   - splits 'i' into:
	//       * 'b' : body/border selector (tuple-like dim, values 0 or 1),
	//       * 'I' : block index,
	//       * 'i' : index within block,
	//   - handles incomplete last block via the 'b' dimension,
	//   - preserves the physical layout of A and tmp.
	//
	// The block size is a tuning parameter; 64 works well on many x64 CPUs
	// with 64B cache lines, but can be adjusted for different machines.
	// -------------------------------------------------------------------------
	constexpr std::size_t I_BLOCK = 64; // tunable row block size for 'i'

	auto row_blocks_proto =
		noarr::into_blocks_static<'i', 'b', 'I', 'i'>(noarr::lit<I_BLOCK>);

	#pragma scop
	// Traverse blocks of rows ('b','I'), then rows within each block ('i').
	// We use a traverser over (A, tmp); the traversal state contains both 'i'
	// and 'j', and is also valid for indexing x and y (they only care about 'j').
	traverser(A, tmp)
		.order(row_blocks_proto)
		.template for_dims<'b', 'I'>([&](auto block_trav) {

			// For each individual row i in this block
			block_trav.template for_dims<'i'>([&](auto inner) {

				// State with fixed i (only 'i' index is fixed here)
				auto si = inner.state();

				// tmp[i] accumulated in a local scalar to reduce memory traffic.
				num_t tmp_i = static_cast<num_t>(0);

				// -----------------------------------------------------------------
				// First inner loop:
				//   tmp[i] = sum_j A[i][j] * x[j]
				// The traverser 'inner' has 'i' fixed; for_each iterates 'j'.
				// -----------------------------------------------------------------
				inner.for_each([&](auto state) {
					// state contains at least 'i' and 'j'.
					tmp_i += A[state] * x[state];
				});

				// Store the computed tmp[i] exactly once.
				tmp[si] = tmp_i;

				// -----------------------------------------------------------------
				// Second inner loop:
				//   y[j] += A[i][j] * tmp[i]
				// We reuse the locally computed tmp_i to avoid reloading tmp[i]
				// in each iteration.
				// -----------------------------------------------------------------
				inner.for_each([&](auto state) {
					y[state] += A[state] * tmp_i;
				});
			});
		});
	#pragma endscop
}

