	DEFINE_PROTO_STRUCT(y_layout, j_vec);

	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);

	// Tuning parameter: block size in the 'j' (column) dimension.
	// This is used for cache- and vectorization‑friendly strip‑mining of the
	// inner loops in the main kernel. It can be adjusted for a given machine.
	static constexpr std::size_t j_block = 64;
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------

void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	num_t fn = static_cast<num_t>(n_len);

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) / fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// Precompute denominator once (constant for all i,j)
	const num_t denom = static_cast<num_t>(5) * static_cast<num_t>(m_len);

	// A[i][j] = ((i + j) % n) / (5 * m)
	// Use a 2D traversal so that the row index 'i' is obtained only once per
	// inner j-loop, improving clarity and slightly reducing index work.
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto si = trav_i.state(); // contains fixed 'i'
		trav_i.template for_each<'j'>([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			num_t numerator = static_cast<num_t>((i + j) % n_len_A);
			A[state] = numerator / denom;
		});
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
//
// Original mathematical definition:
//
// tmp[i] = sum_j A[i][j] * x[j]
// y[j]   = sum_i A[i][j] * tmp[i]
//
// The original implementation interleaved these as:
//
//   y[:] = 0
//   for i:
//     tmp[i] = 0
//     for j: tmp[i] += A[i][j] * x[j]
//     for j: y[j]   += A[i][j] * tmp[i]
//
// Below we keep the same mathematics but restructure the execution as:
//
//   y[:]   = 0
//   tmp[:] = 0
//   // Stage 1: compute tmp for all i
//   for i:
//     for j: tmp[i] += A[i][j] * x[j]
//   // Stage 2: accumulate y using the fully computed tmp
//   for i:
//     for j: y[j]   += A[i][j] * tmp[i]
//
// This reordering is semantically equivalent: Stage 1 only writes tmp,
// Stage 2 only reads tmp and writes y. The sequence of updates to y is
// unchanged relative to the original kernel, so floating‑point results
// for y are bit‑identical.
//
// Additionally, both stages use a strip‑mined traversal of the 'j'
// dimension via into_blocks_dynamic, parameterized by tuning::j_block,
// to expose cache‑ and vectorization‑friendly blocks while preserving
// the logical j-order (0..N-1) within each row.
// -----------------------------------------------------------------------------

[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	// ---------------------------------------------------------------------
	// Initialization of y and tmp
	// ---------------------------------------------------------------------
	#pragma scop
	// y[:] = 0;
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// tmp[:] = 0;
	traverser(tmp).for_each([&](auto si) {
		tmp[si] = static_cast<num_t>(0);
	});

	// ---------------------------------------------------------------------
	// Common strip-mining proto-structure for the 'j' dimension.
	//
	// We use into_blocks_dynamic to be correct even when N is not a
	// multiple of tuning::j_block. The additional "presence" dimension
	// (here named 'p') is used internally by the traversal; states we
	// receive are still in terms of the original dimensions ('i', 'j'),
	// so no special handling is required in the kernel code.
	//
	// Block size is provided as a static value (noarr::lit<...>) so that
	// the compiler can fully exploit constant folding and unrolling.
	// ---------------------------------------------------------------------
	constexpr std::size_t jb = tuning.j_block;
	auto j_blocking =
		into_blocks_dynamic<'j', 'J', 'j', 'p'>(noarr::lit<jb>);

	// ---------------------------------------------------------------------
	// Stage 1: tmp[i] = sum_j A[i][j] * x[j]
	//
	// Traversal order:
	//   for i in [0, M)
	//     for J over j-blocks
	//       for j within block J (in increasing order)
	//
	// Because into_blocks_dynamic preserves the global j‑order within each
	// (i, J) block, the sequence of operations on tmp[i] is exactly the
	// same as in the original kernel (j = 0..N-1), only grouped logically
	// into blocks. This maintains bit‑identical results while giving the
	// compiler a regular, cache‑friendly access pattern.
	// ---------------------------------------------------------------------
	traverser(A, x, tmp)
		.order(j_blocking)
		.template for_dims<'i', 'J'>([&](auto trav_iJ) {
			// trav_iJ has 'i' and the j-block index 'J' fixed.
			// Its state is expressed in the original dimensions; it
			// contains the fixed 'i' index and no explicit 'J'.
			auto si = trav_iJ.state(); // carries 'i', suitable for tmp

			trav_iJ.for_each([&](auto s) {
				// s contains ('i', 'j') for a specific element in A and x
				tmp[si] += A[s] * x[s];
			});
		});

	// ---------------------------------------------------------------------
	// Stage 2: y[j] += A[i][j] * tmp[i]
	//
	// Traversal order is the same as in Stage 1 (i outermost, j blocked
	// into contiguous chunks), and therefore the sequence of updates to
	// every y[j] is identical to the original kernel:
	//
	//   for i = 0..M-1
	//     for j = 0..N-1
	//       y[j] += A[i][j] * tmp[i];
	//
	// Only the separation of Stage 1 and Stage 2 has changed, which is
	// semantically safe as discussed above.
	// ---------------------------------------------------------------------
	traverser(A, y, tmp)
		.order(j_blocking)
		.template for_dims<'i', 'J'>([&](auto trav_iJ) {
			auto si = trav_iJ.state(); // fixed 'i' index for this row

			trav_iJ.for_each([&](auto s) {
				// s again contains ('i', 'j'); tmp[si] is reused across
				// the entire row, which the compiler can keep in a
				// register.
				y[s] += A[s] * tmp[si];
			});
		});
	#pragma endscop
}

